# ------------------------------------------------- dependency-free column path
def _as_column(value: Any, length: int) -> list[int]:
    return value if isinstance(value, list) else [int(value)] * length


def evaluate_term_column(term: Term, prepared: Any, env: Env | None = None) -> Any:
    """Exact term value over a :class:`ColumnFrame`: an int, or a list of ints."""
    env = env or {}
    if isinstance(term, Constant):
        return int(term.value)
    if isinstance(term, SymbolRef):
        return prepared.data[term.name]
    if isinstance(term, IndexedRef):
        return prepared.data[resolve_indexed_name(term, env, prepared.context_families)]
    if isinstance(term, BinaryTerm):
        length = prepared.length
        left = _as_column(evaluate_term_column(term.left, prepared, env), length)
        right = _as_column(evaluate_term_column(term.right, prepared, env), length)
        if term.op == "+":
            return list(map(operator.add, left, right))
        if term.op == "-":
            return list(map(operator.subtract, left, right))
        if term.op == "*":
            return list(map(operator.mul, left, right))
        raise ValueError(f"Unsupported term op: {term.op}")
    if isinstance(term, FuncCall):
        length = prepared.length
        name = term.name.lower()
        columns = [_as_column(evaluate_term_column(arg, prepared, env), length) for arg in term.args]
        if name == "sum":
            total = columns[0]
            for column in columns[1:]:
                total = list(map(operator.add, total, column))
            return total
        if name in {"min", "max"}:
            chooser = min if name == "min" else max
            total = columns[0]
            for column in columns[1:]:
                total = list(map(chooser, total, column))
            return total
        raise ValueError(f"Unsupported function: {term.name}")
    raise TypeError(f"Unsupported term node: {type(term)!r}")


SCALAR_COMPARATORS = {
    "=": operator.eq,
    "!=": operator.ne,
    "<": operator.lt,
    "<=": operator.le,
    ">": operator.gt,
    ">=": operator.ge,
}


def evaluate_formula_column(formula: Formula, prepared: Any, env: Env | None = None) -> list[bool]:
    """Truth values of ``formula`` over a :class:`ColumnFrame` as a bool list."""
    env = env or {}
    length = prepared.length
    if isinstance(formula, BoolConst):
        return [bool(formula.value)] * length
    if isinstance(formula, Compare):
        left = evaluate_term_column(formula.left, prepared, env)
        right = evaluate_term_column(formula.right, prepared, env)
        comparator = SCALAR_COMPARATORS[formula.op]
        if isinstance(left, list) or isinstance(right, list):
            left = _as_column(left, length)
            right = _as_column(right, length)
            return list(map(comparator, left, right))
        return [bool(comparator(left, right))] * length
    if isinstance(formula, BoolNot):
        return [not value for value in evaluate_formula_column(formula.value, prepared, env)]
    if isinstance(formula, BoolAnd):
        return _fold_column(formula.values, prepared, env, operator.and_, True)
    if isinstance(formula, BoolOr):
        return _fold_column(formula.values, prepared, env, operator.or_, False)
    if isinstance(formula, Implies):
        left = evaluate_formula_column(formula.left, prepared, env)
        right = evaluate_formula_column(formula.right, prepared, env)
        return list(map(lambda a, b: (not a) or b, left, right))
    if isinstance(formula, (ForAll, Exists)):
        identity = isinstance(formula, ForAll)
        accumulator: list[bool] | None = None
        for value in formula.domain:
            body = evaluate_formula_column(formula.body, prepared, {**env, formula.variable: value})
            if accumulator is None:
                accumulator = list(body)
            else:
                combine = operator.and_ if identity else operator.or_
                accumulator = list(map(combine, accumulator, body))
        return [identity] * length if accumulator is None else accumulator
    raise TypeError(f"Unsupported formula node: {type(formula)!r}")


def _fold_column(
    values: Iterable[Formula], prepared: Any, env: Env, operation: Any, identity: bool
) -> list[bool]:
    accumulator: list[bool] | None = None
    for value in values:
        child = evaluate_formula_column(value, prepared, env)
        accumulator = list(child) if accumulator is None else list(map(operation, accumulator, child))
    return [identity] * prepared.length if accumulator is None else accumulator
